struct Reader{std::vector<unsigned char>b;size_t p=0;unsigned get(unsigned n){if(n>b.size()-p)throw std::runtime_error("truncated");unsigned v=0;for(unsigned i=0;i<n;++i)v|=unsigned(b[p++])<<(8*i);return v;}};
int main(int argc,char**argv)try{if(argc!=2)return 2;std::ifstream f(argv[1],std::ios::binary);Reader r{{std::istreambuf_iterator<char>(f),{}}};if(r.b.size()!=669800||mfrk::ui::scene::scope::test::sha256(r.b)!=std::array<std::uint8_t,32>{0x61,0x47,0x26,0x45,0xa4,0xfd,0x18,0x77,0x00,0xc5,0xaa,0xa9,0x36,0xf5,0xbb,0x35,0x9f,0x1d,0x4a,0x78,0xca,0x8b,0xad,0x59,0x2b,0xe1,0xac,0x49,0x3d,0xfc,0x04,0x75})throw std::runtime_error("fixture identity");for(char c:std::array<char,8>{'M','F','C','B','A','N','K','1'})if(r.get(1)!=unsigned(c))return 2;auto count=r.get(4);if(count!=7738)return 2;auto seed=r.get(4);if(seed!=54321)return 2;mfrk::core_bank::Tables tables;mfrk::karplus::SharedRandom rng{seed};std::array<std::unique_ptr<mfrk::core_bank::Side>,12>bank;for(unsigned i=0;i<12;++i)bank[i]=std::make_unique<mfrk::core_bank::Side>(tables,rng,0x400020000ull+i*16384);unsigned long long audio=0,random=0,flags=0,memory=0;unsigned renders=0;for(unsigned i=0;i<count;++i){auto op=r.get(1),side=r.get(1),model=r.get(1),reserved=r.get(1);auto a=r.get(4),b=r.get(4),x=r.get(4),y=r.get(4),expectedrng=r.get(4),retval=r.get(4);if(reserved)return 2;if(op==254){if(side>=6||a>255||b||x||y||expectedrng||retval)return 2;bank[side*2]->owner_policy(static_cast<unsigned char>(a));bank[side*2+1]->owner_policy(static_cast<unsigned char>(a));continue;}if(side>=12||model>=7)return 2;auto m=static_cast<mfrk::core_bank::Model>(model);auto&s=*bank[side];switch(op){case 0:if(a>2)return 2;flags+=s.word(m,a)!=(retval&65535);break;case 1:s.reset(m);break;case 2:{std::array<float,32>o{};if(!s.render(m,o)){std::cerr<<"render failure event "<<i<<'\n';return 1;}for(unsigned j=0;j<32;++j){auto expected=r.get(4);if(std::bit_cast<unsigned>(o[j])!=expected){if(audio<8)std::cerr<<"event "<<i<<" side "<<side<<" model "<<model<<" sample "<<j<<" actual "<<std::hex<<std::bit_cast<unsigned>(o[j])<<" expected "<<expected<<std::dec<<'\n';++audio;}}++renders;break;}case 3:s.prepare(m);break;case 4:s.initialize(m);break;case 5:if(a>1)return 2;s.trigger(m,static_cast<unsigned char>(a));break;case 6:s.pitch(m,std::bit_cast<float>(x),std::bit_cast<float>(y));break;case 7:s.phase(m,std::bit_cast<float>(x));break;case 8:if(b!=16384)return 2;s.bind(m,b);break;case 9:break;case 11:flags+=s.active(m)!=(retval&255);break;case 12:if(a>1)return 2;s.active(m,static_cast<unsigned char>(a));break;case 13:if(a>2||b>65535)return 2;s.word(m,a,static_cast<unsigned short>(b));break;case 14:if(a>2||b>255)return 2;s.dirty(m,a,static_cast<unsigned char>(b));break;default:return 2;}random+=rng.value!=expectedrng;}for(auto&s:bank)for(auto word:s->memory())memory+=std::bit_cast<unsigned short>(word)!=r.get(2);if(r.p!=r.b.size())return 2;std::cout<<"Original fullowner callback bank: "<<count<<" events "<<renders<<" renders audio "<<audio<<" rng "<<random<<" flags "<<flags<<" finalMemory "<<memory<<'\n';return audio||random||flags||memory?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}
